'use strict';
// Floating waveform display; detection and acquisition remain unchanged.
const waveformWindow=$('unitInset'),waveformHandle=$('waveformWindowHandle');let waveformWindowPlacement=null,waveformWindowPlaceholder=null,waveformWindowDrag=null;
function placeWaveformWindow(){if(!waveformWindowPlacement)return;const p=waveformWindowPlacement,maxWidth=Math.max(180,Math.min(window.innerWidth-16,(window.innerHeight-50)*1.5));p.width=Math.min(maxWidth,p.width);waveformWindow.style.width=p.width+'px';p.height=Math.max(170,Math.min(window.innerHeight-16,p.height||190));waveformWindow.style.height=p.height+'px';const h=waveformWindow.getBoundingClientRect().height;p.left=Math.max(8,Math.min(window.innerWidth-p.width-8,p.left));p.top=Math.max(8,Math.min(window.innerHeight-h-8,p.top));waveformWindow.style.left=p.left+'px';waveformWindow.style.top=p.top+'px';}
function floatWaveformWindow(){if(waveformWindowPlacement)return;const r=waveformWindow.getBoundingClientRect();waveformWindowPlaceholder=document.createComment('Waveform docking point');waveformWindow.before(waveformWindowPlaceholder);document.body.appendChild(waveformWindow);waveformWindow.classList.add('floatingWaveform');waveformWindowPlacement={left:r.left,top:r.top,width:r.width||255,height:r.height||190};placeWaveformWindow();}
function saveWaveformWindow(){try{if(waveformWindowPlacement)localStorage.setItem('visual-rig-waveform-window',JSON.stringify(waveformWindowPlacement));else localStorage.removeItem('visual-rig-waveform-window');}catch{}}
$('dockWaveform').onclick=()=>{if(!waveformWindowPlacement)return;waveformWindowPlaceholder.replaceWith(waveformWindow);waveformWindowPlaceholder=null;waveformWindowPlacement=null;waveformWindow.classList.remove('floatingWaveform');waveformWindow.style.width='';waveformWindow.style.height='';waveformWindow.style.left='';waveformWindow.style.top='';saveWaveformWindow();};
waveformHandle.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;e.preventDefault();floatWaveformWindow();waveformWindowDrag={x:e.clientX,y:e.clientY,left:waveformWindowPlacement.left,top:waveformWindowPlacement.top};waveformHandle.setPointerCapture(e.pointerId);});waveformHandle.addEventListener('pointermove',e=>{if(!waveformWindowDrag)return;waveformWindowPlacement.left=waveformWindowDrag.left+e.clientX-waveformWindowDrag.x;waveformWindowPlacement.top=waveformWindowDrag.top+e.clientY-waveformWindowDrag.y;placeWaveformWindow();});waveformHandle.addEventListener('pointerup',()=>{waveformWindowDrag=null;saveWaveformWindow();});waveformHandle.addEventListener('pointercancel',()=>{waveformWindowDrag=null;saveWaveformWindow();});window.addEventListener('resize',()=>{placeWaveformWindow();saveWaveformWindow();});
try{const p=JSON.parse(localStorage.getItem('visual-rig-waveform-window')||'null');if(p&&['left','top','width'].every(k=>Number.isFinite(p[k]))){floatWaveformWindow();waveformWindowPlacement=p;placeWaveformWindow();}}catch{}

const waveformResizeGrip=document.createElement('div');waveformResizeGrip.className='waveformResizeGrip';waveformResizeGrip.title='Drag to resize waveform view';waveformWindow.appendChild(waveformResizeGrip);let waveformResize=null;
waveformResizeGrip.addEventListener('pointerdown',e=>{e.preventDefault();floatWaveformWindow();waveformResize={x:e.clientX,y:e.clientY,width:waveformWindowPlacement.width,height:waveformWindowPlacement.height};waveformResizeGrip.setPointerCapture(e.pointerId);});waveformResizeGrip.addEventListener('pointermove',e=>{if(!waveformResize)return;waveformWindowPlacement.width=Math.max(220,waveformResize.width+e.clientX-waveformResize.x);waveformWindowPlacement.height=Math.max(170,waveformResize.height+e.clientY-waveformResize.y);placeWaveformWindow();});waveformResizeGrip.addEventListener('pointerup',()=>{waveformResize=null;saveWaveformWindow();});waveformResizeGrip.addEventListener('pointercancel',()=>{waveformResize=null;saveWaveformWindow();});
